def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    total_length = sum(len(content) for content in cells.values())
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 10 * total_length + 10000))

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]")
    cell_pattern = re.compile(r"[A-Z][1-9][0-9]?")

    def parse(formula):
        tokens = token_pattern.findall(formula)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = ("binary", op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = ("binary", op, node, unary())
            return node

        def unary():
            nonlocal pos
            negative = False
            while pos < len(tokens) and tokens[pos] == "-":
                negative = not negative
                pos += 1
            node = atom()
            return ("neg", node) if negative else node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if cell_pattern.fullmatch(token):
                return ("cell", token)

            name = token
            pos += 1  # (

            if name == "IF":
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)

            args = []
            while True:
                if (
                    pos + 1 < len(tokens)
                    and cell_pattern.fullmatch(tokens[pos])
                    and tokens[pos + 1] == ":"
                ):
                    args.append(("range", tokens[pos], tokens[pos + 2]))
                    pos += 3
                else:
                    args.append(expression())

                if tokens[pos] == ")":
                    pos += 1
                    break
                pos += 1  # ,

            return ("function", name, args)

        return expression()

    values = {}
    in_progress = set()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in in_progress:
            return "#CYCLE!"

        in_progress.add(name)
        content = cells[name]
        if content.startswith("="):
            value = evaluate(parse(content[1:]))
        else:
            value = int(content)
        in_progress.remove(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]

        if kind == "cell":
            return cell_value(node[1])

        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind == "binary":
            op, left_node, right_node = node[1:]
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right

            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            op, left_node, right_node, then, otherwise = node[1:]
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right

            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(then if condition else otherwise)

        name, args = node[1:]
        result = None

        def combine(current, value):
            if current is None:
                return value
            if name == "SUM":
                return current + value
            if name == "MIN":
                return min(current, value)
            return max(current, value)

        for arg in args:
            if arg[0] == "range":
                first, last = arg[1], arg[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        cell = chr(col) + str(row)
                        if cell not in cells:
                            continue
                        value = cell_value(cell)
                        if isinstance(value, str):
                            return value
                        result = combine(result, value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                result = combine(result, value)

        return 0 if result is None else result

    return {name: cell_value(name) for name in cells}
